utility_source = '"""Shared chronological protocol operations for D1 small-sample experiments."""\n\nimport json\nimport math\nfrom pathlib import Path\n\nimport numpy as np\n\nMINUTES_PER_DAY = 1440\nHISTORY_POINTS = 30 * MINUTES_PER_DAY\nFORECAST_POINTS = MINUTES_PER_DAY\nTRAIN_END = 511 * MINUTES_PER_DAY\nBUDGET_DAYS = {"9m": 270, "6m": 180, "3m": 90, "1m": 30}\n\n\ndef read_json(path):\n    return json.loads(Path(path).read_text(encoding="utf-8"))\n\n\ndef write_json(path, value):\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n\n\ndef normalization_stats(values, observed, start, end):\n    """Fit five-channel population statistics using permitted real observations."""\n    measured = np.where(observed[start:end], values[start:end], np.nan)\n    mean = np.nanmean(measured, axis=0)\n    std = np.nanstd(measured, axis=0)\n    return {\n        "start": int(start),\n        "end": int(end),\n        "endpoint_convention": "half-open",\n        "mean": mean.tolist(),\n        "std": std.tolist(),\n        "observed_counts": observed[start:end].sum(axis=0).tolist(),\n        "policy": "Only valid_observed entries; no outer validation/test or imputed values.",\n        "std_ddof": 0,\n    }\n\n\ndef build_oof_layout(origins, context_start, forecast_points=FORECAST_POINTS):\n    """Use one initial block and three forward prediction blocks, with purged holdouts."""\n    origins = sorted(int(origin) for origin in origins)\n    quotient, remainder = divmod(len(origins), 4)\n    blocks = []\n    offset = 0\n    for block_index in range(4):\n        size = quotient + int(block_index < remainder)\n        blocks.append(origins[offset:offset + size])\n        offset += size\n\n    folds = []\n    for index in range(1, 4):\n        predictions = blocks[index]\n        if not predictions:\n            raise ValueError(f"OOF fold {index} has no prediction window.")\n        prediction_start = predictions[0]\n        preceding = [origin for block in blocks[:index] for origin in block]\n        eligible = [origin for origin in preceding if origin + forecast_points <= prediction_start]\n        validation_count = max(1, math.ceil(0.2 * len(eligible)))\n        validation = eligible[-validation_count:]\n        if not validation:\n            raise ValueError(f"OOF fold {index} has no internal validation window.")\n        validation_start = validation[0]\n        training = [origin for origin in eligible[:-validation_count]\n                    if origin + forecast_points <= validation_start]\n        if not training:\n            raise ValueError(f"OOF fold {index} has no training window after 24-hour label purging.")\n        folds.append({\n            "fold": index,\n            "train_origins": training,\n            "validation_origins": validation,\n            "prediction_origins": predictions,\n            "prediction_start": prediction_start,\n            "prediction_label_end": predictions[-1] + forecast_points,\n            "normalization_start": int(context_start),\n            "normalization_end": validation_start,\n            "training_labels_end_before_internal_validation": validation_start,\n            "fit_labels_end_before_prediction": prediction_start,\n            "purged_origins": [origin for origin in preceding\n                               if origin not in training and origin not in validation],\n        })\n    return folds\n\n\ndef build_oof_folds(origins, values, observed, context_start):\n    folds = build_oof_layout(origins, context_start)\n    for fold in folds:\n        fold["normalization"] = normalization_stats(\n            values, observed, fold["normalization_start"], fold["normalization_end"])\n        fold["mean"] = fold["normalization"]["mean"]\n        fold["std"] = fold["normalization"]["std"]\n    return folds\n\n\ndef measured_target_counts(observed, origins, forecast_points=FORECAST_POINTS):\n    counts = np.asarray([observed[origin:origin + forecast_points].sum(axis=0)\n                         for origin in origins])\n    return {\n        "selected": len(origins),\n        "measured_targets": counts.sum(axis=0).tolist(),\n        "minimum_observed_per_channel": counts.min(axis=0).tolist(),\n    }\n'
prepare_source = '"""Prepare D1 9/6/3/1-month protocols; this entry point never trains or predicts."""\n\nimport argparse\nfrom pathlib import Path\n\nimport numpy as np\n\nfrom protocol_utils import (\n    BUDGET_DAYS, FORECAST_POINTS, HISTORY_POINTS, MINUTES_PER_DAY, TRAIN_END,\n    build_oof_folds, build_oof_layout, measured_target_counts,\n    normalization_stats, read_json, write_json,\n)\n\nHERE = Path(__file__).resolve().parent\n\n\ndef budget_bounds(name, one_month_period):\n    if name == "1m" and one_month_period == "coverage30":\n        return 640800, 684000\n    return TRAIN_END - BUDGET_DAYS[name] * MINUTES_PER_DAY, TRAIN_END\n\n\ndef prepare_protocols(data_path, output_root, baseline_protocol_path, a2_origins_path,\n                      one_month_period="latest30"):\n    baseline = read_json(baseline_protocol_path)\n    temperature_origins = read_json(a2_origins_path)\n    shared = sorted(set(baseline["origins"]["train"]) & set(temperature_origins["train"]))\n    selected = {}\n    for name, days in BUDGET_DAYS.items():\n        label_start, label_end = budget_bounds(name, one_month_period)\n        train = [int(origin) for origin in shared\n                 if origin >= label_start and origin + FORECAST_POINTS <= label_end]\n        # Stage feasibility is part of this protocol, rather than a full-data fallback.\n        build_oof_layout(train, label_start - HISTORY_POINTS)\n        selected[name] = train\n\n    with np.load(data_path) as data:\n        values = data["values"].astype(np.float64)\n        observed = data["valid_observed"].astype(bool)\n        available = data["input_available_at"]\n\n    for name, days in BUDGET_DAYS.items():\n        label_start, label_end = budget_bounds(name, one_month_period)\n        context_start = label_start - HISTORY_POINTS\n        origins = {\n            "train": selected[name],\n            "val": [int(origin) for origin in baseline["origins"]["val"]],\n            "test": [int(origin) for origin in baseline["origins"]["test"]],\n        }\n        for split_origins in origins.values():\n            for origin in split_origins:\n                if not np.all(available[origin - HISTORY_POINTS:origin] < origin):\n                    raise ValueError(f"Non-causal minute history at origin {origin}.")\n        h1_pretraining_origins = {}\n        h1_pretraining_selection = {}\n        a2_unavailable_reasons = []\n        h1_future_offsets = np.arange(0, FORECAST_POINTS, 15)\n        for split in ("train", "val"):\n            candidates = origins[split]\n            temperature_observed = observed[\n                np.asarray(candidates)[:, None] + h1_future_offsets, 0]\n            complete = temperature_observed.all(axis=1)\n            retained = [origin for origin, keep in zip(candidates, complete) if keep]\n            missing_nodes = int((~temperature_observed).sum())\n            h1_pretraining_origins[split] = retained\n            h1_pretraining_selection[split] = {\n                "candidates": len(candidates),\n                "selected": len(retained),\n                "rejected_missing_temperature_windows": len(candidates) - len(retained),\n                "missing_temperature_nodes": missing_nodes,\n            }\n            if not retained:\n                a2_unavailable_reasons.append(\n                    f"{name} H1 pretraining {split}: no complete observed-temperature "\n                    f"window at the 15-minute teacher grid; candidates={len(candidates)}, "\n                    f"rejected_windows={len(candidates)}, missing_temperature_nodes={missing_nodes}.")\n        h1_training_origins = h1_pretraining_origins["train"]\n        if h1_training_origins:\n            teacher_available = available[\n                np.asarray(h1_training_origins)[:, None] + h1_future_offsets, 1:]\n            teacher_max_available = int(teacher_available.max())\n            teacher_cross_budget = int((teacher_available >= label_end).any(axis=(1, 2)).sum())\n        else:\n            teacher_max_available = None\n            teacher_cross_budget = 0\n        normalization = normalization_stats(values, observed, context_start, label_end)\n        folds = build_oof_folds(origins["train"], values, observed, context_start)\n        adaptation_origins = sorted(origin for fold in folds for origin in fold["prediction_origins"])\n        protocol = {\n            "version": "d1_small_sample_9_6_3_1_months_20261013",\n            "budget": name,\n            "budget_days": days,\n            "one_month_period": one_month_period,\n            "period": one_month_period if name == "1m" else "latest_budget",\n            "a2_trainable": not a2_unavailable_reasons,\n            "a2_unavailable_reason": "; ".join(a2_unavailable_reasons) or None,\n            "data_path": str(Path(data_path).resolve()),\n            "source_shape": list(values.shape),\n            "source_arrays": ["values", "valid_observed", "input_available_at"],\n            "source_arrays_modified": False,\n            "baseline_protocol_source": str(Path(baseline_protocol_path).resolve()),\n            "a2_origins_source": str(Path(a2_origins_path).resolve()),\n            "origins": origins,\n            "mean": normalization["mean"],\n            "std": normalization["std"],\n            "normalization": normalization,\n            "channel_names": baseline["channels"],\n            "channels": baseline["channels"],\n            "units": baseline["units"],\n            "sample_minutes": 1,\n            "history_points": HISTORY_POINTS,\n            "forecast_points": FORECAST_POINTS,\n            "future_points": FORECAST_POINTS,\n            "label_start": label_start,\n            "label_end": label_end,\n            "context_start": context_start,\n            "budget_definition": "30 days per month; supervised labels lie wholly inside the budget; preceding 30-day context is permitted.",\n            "normalization_policy": "Final fit uses observed values in [context_start, label_end); each OOF fit stops at its first internal validation origin, excluding internal holdout targets from statistics.",\n            "counts": {split: measured_target_counts(observed, starts)\n                       for split, starts in origins.items()},\n            "oof_folds": folds,\n            "h1_adaptation_origins": adaptation_origins,\n            "prfm_adaptation_origins": adaptation_origins,\n            "h1_pretraining_origins": h1_pretraining_origins,\n            "h1_pretraining_selection": h1_pretraining_selection,\n            "h1_teacher_source_audit": {\n                "source": "Original filled displacement targets used by the FFT component teachers.",\n                "sample_minutes": 15,\n                "future_points": len(h1_future_offsets),\n                "training_windows": len(h1_training_origins),\n                "label_end": label_end,\n                "max_input_available_at": teacher_max_available,\n                "cross_budget_teacher_windows": teacher_cross_budget,\n            },\n            "h1_pretraining_policy": "Past input sampled every 15 minutes; all 96 future teacher-temperature nodes must be valid_observed; displacement point losses use valid_observed masks; component teachers retain the original FFT construction from filled displacement targets.",\n            "prfm_pretraining_origins": h1_pretraining_origins["train"],\n            "final_temperature_training_origins": origins["train"],\n            "oof_policy": "One initial chronological block and three prediction blocks; all fit labels finish by the first prediction origin; inner training labels finish by the first holdout origin.",\n            "causal_history": "Every consumed minute and channel has input_available_at < prediction origin.",\n            "target_policy": "Point losses and metrics use only valid_observed future labels. H1 component teachers retain the original FFT construction from filled displacement targets before applying observed-point loss masks.",\n            "outer_validation_policy": "Same frozen 26 validation origins for every budget and model.",\n            "test_policy": "Same frozen 39 test origins; test does not select checkpoints or tune configurations.",\n        }\n        output_path = Path(output_root) / "protocols" / name / "protocol.json"\n        write_json(output_path, protocol)\n        print(f"{name}: train={len(origins[\'train\'])}, val={len(origins[\'val\'])}, "\n              f"test={len(origins[\'test\'])}, OOF={len(adaptation_origins)}, "\n              f"H1 pretrain train={len(h1_pretraining_origins[\'train\'])}, "\n              f"val={len(h1_pretraining_origins[\'val\'])}, "\n              f"A2 trainable={not a2_unavailable_reasons} -> {output_path}", flush=True)\n        if a2_unavailable_reasons:\n            print("; ".join(a2_unavailable_reasons), flush=True)\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--data", required=True, type=Path)\n    parser.add_argument("--output-root", required=True, type=Path)\n    parser.add_argument("--baseline-protocol", type=Path,\n                        default=HERE / "metadata" / "baseline_protocol.json")\n    parser.add_argument("--a2-origins", type=Path,\n                        default=HERE / "metadata" / "a2_window_origins.json")\n    parser.add_argument("--one-month-period", choices=("latest30", "coverage30"),\n                        default="latest30",\n                        help="latest30 keeps the original training endpoint; coverage30 explicitly uses 2023-03-22 through 2023-04-20.")\n    args = parser.parse_args()\n    prepare_protocols(args.data, args.output_root, args.baseline_protocol, args.a2_origins,\n                      args.one_month_period)\n\n\nif __name__ == "__main__":\n    main()\n'
